import{_ as t,l,o as e,c as o,v as r,p as s,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"损失厌恶与参考点","description":"","frontmatter":{"title":"损失厌恶与参考点","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/loss-aversion-reference.md","filePath":"econ/loss-aversion-reference.md","lastUpdated":1789023840000}'),m={name:"econ/loss-aversion-reference.md"};function c(h,a,A,_,b,B){const n=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="损失厌恶与参考点" tabindex="-1">损失厌恶与参考点 <a class="header-anchor" href="#损失厌恶与参考点" aria-label="Permalink to &quot;损失厌恶与参考点&quot;">​</a></h1><div class="epigraph"><p>损失的痛苦大于同等收益的快乐；没有参考点，这句话没有单位。</p><footer>—— Tversky and Kahneman, Loss Aversion in Riskless Choice: A Reference-Dependent Model, QJE 1991；对照 Kőszegi and Rabin, QJE 2006</footer></div><p><a href="/econ/prospect-theory">上一课</a>同时引入 \\(v\\) 与 \\(\\pi\\)。本课只拆损失厌恶：参考点两侧斜率不同，\\(\\lambda\\gt 1\\)。不重写权重函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1979 年的 \\(v\\) 在零点拐折，损失段更陡。Tversky 与 Kahneman（1991）把同一逻辑写进无风险选择：买价与卖价缺口、现状偏误，不必有概率。参考点通常是现状、期望或刚实现的价格。Kőszegi 与 Rabin（2006）让参考点等于对结果的理性预期：人同时消费「消费效用」与「得-失效用」，均衡要求预期与选择一致。缺口是把拐折从实验室彩票接到状态依存的参考，而不是再推 <a href="/econ/expected-utility">vNM</a>。</p><p>家庭金融接口：股票相对买入价被编码成浮盈/浮亏，处置效应后课再写；本课只钉 \\(\\lambda\\) 与参考点的定义。</p><p><span class="marginnote">损失厌恶不是风险厌恶。\\(\\lambda\\) 比较的是参考点两侧的斜率；\\(\\gamma\\) 比较的是财富上 \\(u\\) 的弯曲。Benartzi–Thaler 的短视损失厌恶把两者乘在评价频率上，那是定价课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(v(x)=x\\)（收益）与 \\(v(x)=\\lambda x\\)（损失，\\(x\\lt 0\\)），或对凹/凸形状再加弯曲。风险中性加损失厌恶已经足以产生对小赌注的拒绝——Rabin 校准指出，vNM 若拒绝小赌注会推出对大赌注的荒谬拒绝；损失厌恶避开这条。参考点的选取：现状、买入价、KR 预期。本课不估计 \\(\\lambda\\approx 2\\) 的来源实验细节。</p>',9)),(e(),s(E,null,{default:i(()=>[p(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E5%89%8D%E6%99%AF%3A%20v%20%E5%9C%A8%E9%9B%B6%E7%82%B9%E6%8B%90%E6%8A%98%22%5D%20--%3E%20LA%5B%22%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%20lambda%22%5D%0A%20%20LA%20--%3E%20STAT%5B%22%E5%8F%82%E8%80%83%E7%82%B9%3A%20%E7%8E%B0%E7%8A%B6%E6%88%96%E4%B9%B0%E5%85%A5%E4%BB%B7%22%5D%0A%20%20LA%20--%3E%20KR%5B%22Koszegi-Rabin%3A%20%E9%A2%84%E6%9C%9F%E5%8D%B3%E5%8F%82%E8%80%83%22%5D%0A%20%20LA%20--%3E%20ENDW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E7%A6%80%E8%B5%8B%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是不对称编码。从参考点向上走一单位，价值增 \\(1\\)；向下走一单位，价值减 \\(\\lambda\\)。因此放弃已持有的物品被编码为损失，获得未持有的物品被编码为收益，WTA–WTP 缺口出现——禀赋效应课展开。在风险上，相对参考点的对称赌注期望为负（若 \\(\\lambda\\gt 1\\)），人拒绝公平硬币，看起来像极度厌恶风险。</p><p>参考点移动时，同一期末财富的评价翻转。这与指数贴现的时间不一致不同：这里甚至不必跨期，一期菜单改框架即可。</p><p>Rabin 校准的逻辑要写清：若 vNM 在小赌注上拒绝公平硬币，凹性会在大赌注上爆炸；损失厌恶把「拒绝小赌注」从曲率挪到拐折，大赌注仍可被接受。KR 的预期参考点使已预期的工资不产生得失，未预期的奖金才进入 \\(v\\)——这与现状参考点对工资刚性、对股票买入价的预测不同，后课按对象选用，不混成一个 \\(\\lambda\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并非所有 WTA–WTP 缺口都是 \\(\\lambda\\)：收入效应、实验经验（List 2003 的专业交易者）会缩小缺口。KR 的预期参考点使「意料中的损失」不那么痛，与现状参考点预测不同。本课不把宏观消费欧拉改成损失厌恶欧拉。</p><p>后课默认：损失厌恶是 \\(v\\) 在参考点的斜率比；概率扭曲是另一零件。</p><p>\\(\\lambda\\) 比较参考点两侧斜率，不是 \\(u\\) 的曲率；小赌注拒绝因此不必推出荒谬的大赌注厌恶。</p><p>KR 的预期参考点与现状参考点对工资、对买入价的预测不同，后课按对象选用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>损失厌恶是参考点两侧斜率之比，不是 \\(u\\) 的曲率。</li><li>参考点可以是现状、成本或理性预期（KR）。</li><li>小赌注拒绝不必推出荒谬的大赌注厌恶。</li><li>禀赋效应是现状参考点的现场。</li><li>短视损失厌恶把评价频率留给定价课。</li><li>出处：Tversky and Kahneman, <em>QJE</em> 1991；Kőszegi and Rabin, <em>QJE</em> 2006。</li></ul>',11))])}const T=t(m,[["render",c]]);export{u as __pageData,T as default};
